          COS(usa_r34_se * 1.61 / 6378.1) - SIN(usa_latitude * (3.14159 / 180)) * SIN(
            57.2958 * ASIN(
              SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_se * 1.61 / 6378.1) +
              COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_se * 1.61 / 6378.1) * COS(135 * (3.14159 / 180))
            )
          )
        )
      ),
      57.2958 * ASIN(
        SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_se * 1.61 / 6378.1) +
        COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_se * 1.61 / 6378.1) * COS(135 * (3.14159 / 180))
      )
    ) as se_point,
    ST_GEOGPOINT(
      57.2958 * (
        usa_longitude * (3.14159 / 180) + ATAN2(
          SIN(225 * (3.14159 / 180)) * SIN(usa_r34_sw * 1.61 / 6378.1) * COS(usa_latitude * (3.14159 / 180)),
          COS(usa_r34_sw * 1.61 / 6378.1) - SIN(usa_latitude * (3.14159 / 180)) * SIN(
            57.2958 * ASIN(
              SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_sw * 1.61 / 6378.1) +
              COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_sw * 1.61 / 6378.1) * COS(225 * (3.14159 / 180))
            )
          )
        )
      ),
      57.2958 * ASIN(
        SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_sw * 1.61 / 6378.1) +
        COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_sw * 1.61 / 6378.1) * COS(225 * (3.14159 / 180))
      )
    ) as sw_point,
    ST_GEOGPOINT(
      57.2958 * (
        usa_longitude * (3.14159 / 180) + ATAN2(
          SIN(315 * (3.14159 / 180)) * SIN(usa_r34_nw * 1.61 / 6378.1) * COS(usa_latitude * (3.14159 / 180)),
          COS(usa_r34_nw * 1.61 / 6378.1) - SIN(usa_latitude * (3.14159 / 180)) * SIN(
            57.2958 * ASIN(
              SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_nw * 1.61 / 6378.1) +
              COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_nw * 1.61 / 6378.1) * COS(315 * (3.14159 / 180))
            )
          )
        )
      ),
      57.2958 * ASIN(
        SIN(usa_latitude * (3.14159 / 180)) * COS(usa_r34_nw * 1.61 / 6378.1) +
        COS(usa_latitude * (3.14159 / 180)) * SIN(usa_r34_nw * 1.61 / 6378.1) * COS(315 * (3.14159 / 180))
      )
    ) as nw_point
  FROM storm_obs
),
storm_poly AS (
  SELECT sid, name,
    ST_MAKEPOLYGON(ST_MAKELINE(ARRAY[ne_point, se_point, sw_point, nw_point, ne_point])) as storm_area
  FROM corners
)
SELECT sid, name, ST_AsText(storm_area) as storm_area_text
FROM storm_poly
